function HouseRegistry({onSelectHouse}){
 const [connections,setConnections]=useState([]),[boxes,setBoxes]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[search,setSearch]=useState(''),[drafts,setDrafts]=useState({}),[saving,setSaving]=useState({}),[adding,setAdding]=useState(false),[editingId,setEditingId]=useState(null);
 const [newRow,setNewRow]=useState({boxId:'',cableNumber:'',houseName:'',meterNumber:'',accountNumber:''});
 useEffect(()=>{
  let alive=true;
  const load=async()=>{
   const [{data:cables,error:cableError},{data:boxRows,error:boxError}]=await Promise.all([
    supabase.from('distribution_box_connections').select('id,distribution_box_id,cable_number,house_name,meter_number,account_number').order('distribution_box_id').order('cable_number'),
    supabase.from('distribution_boxes').select('id,box_number').order('box_number')
   ]);
   if(!alive)return;
   const problem=cableError||boxError;
   if(problem){setError(problem.message||'Could not load the cable register.');setLoading(false);return}
   setBoxes(boxRows||[]);
   const boxById=Object.fromEntries((boxRows||[]).map(b=>[b.id,b.box_number]));
   const rows=(cables||[]).filter(c=>String(c.house_name||'').trim()).map(c=>({
    id:c.id,boxId:c.distribution_box_id,boxNumber:boxById[c.distribution_box_id]||'Unmatched box',cableNumber:c.cable_number,houseName:c.house_name,
    meterNumber:c.meter_number||'',accountNumber:c.account_number||''
   })).sort((a,b)=>a.boxNumber.localeCompare(b.boxNumber,undefined,{numeric:true})||a.cableNumber-b.cableNumber);
   setConnections(rows);setDrafts(old=>{const next={...old};rows.forEach(row=>{if(!next[row.id])next[row.id]={boxId:row.boxId,cableNumber:row.cableNumber==null?'':String(row.cableNumber),houseName:row.houseName,meterNumber:row.meterNumber,accountNumber:row.accountNumber}});return next});setError('');setLoading(false);
  };
  load();
  const channel=supabase.channel('house-registry-cable-register')
   .on('postgres_changes',{event:'*',schema:'public',table:'distribution_box_connections'},load)
   .on('postgres_changes',{event:'*',schema:'public',table:'distribution_boxes'},load)
   .subscribe();
  return()=>{alive=false;supabase.removeChannel(channel)};
 },[]);
 const filtered=useMemo(()=>connections.filter(c=>(c.boxNumber+' '+c.cableNumber+' '+c.houseName+' '+c.meterNumber+' '+c.accountNumber).toLowerCase().includes(search.toLowerCase())),[connections,search]);
 const boxCount=new Set(connections.map(c=>c.boxNumber)).size;
 function changeDraft(id,key,value){setDrafts(old=>({...old,[id]:{...(old[id]||{}),[key]:value}}))}
 async function saveRow(row){
  const d=drafts[row.id]||{};if(!d.boxId||!String(d.houseName).trim()){setError('Box Number and House Name are required.');return}
  const cableText=String(d.cableNumber??'').trim();const cable=cableText===''?null:Number(cableText);if(cable!==null&&(!Number.isInteger(cable)||cable<0)){setError('Cable Number must be blank or a whole number of 0 or greater.');return}
  setSaving(old=>({...old,[row.id]:true}));setError('');
  const {error:saveError}=await supabase.from('distribution_box_connections').update({distribution_box_id:d.boxId,cable_number:cable,house_name:d.houseName.trim(),meter_number:String(d.meterNumber||'').trim()||null,account_number:String(d.accountNumber||'').trim()||null,updated_at:new Date().toISOString()}).eq('id',row.id);
  if(saveError)setError('Could not save '+row.houseName+': '+saveError.message);
  else{const b=boxes.find(x=>x.id===d.boxId);setConnections(old=>old.map(x=>x.id===row.id?{...x,boxId:d.boxId,boxNumber:b?.box_number||x.boxNumber,cableNumber:cable,houseName:d.houseName.trim(),meterNumber:String(d.meterNumber||'').trim(),accountNumber:String(d.accountNumber||'').trim()}:x).sort((a,b)=>a.boxNumber.localeCompare(b.boxNumber,undefined,{numeric:true})||a.cableNumber-b.cableNumber))}
  setSaving(old=>({...old,[row.id]:false}));
  if(!saveError)setEditingId(null);
 }
 function startEdit(row){setDrafts(old=>({...old,[row.id]:{boxId:row.boxId,cableNumber:row.cableNumber==null?'':String(row.cableNumber),houseName:row.houseName,meterNumber:row.meterNumber,accountNumber:row.accountNumber}}));setEditingId(row.id);setError('')}
 function cancelEdit(row){setDrafts(old=>({...old,[row.id]:{boxId:row.boxId,cableNumber:row.cableNumber==null?'':String(row.cableNumber),houseName:row.houseName,meterNumber:row.meterNumber,accountNumber:row.accountNumber}}));setEditingId(null);setError('')}
 async function addRow(){
  if(!newRow.boxId||!newRow.houseName.trim()){setError('Box Number and House Name are required.');return}
  const cableText=String(newRow.cableNumber??'').trim();const cable=cableText===''?null:Number(cableText);if(cable!==null&&(!Number.isInteger(cable)||cable<0)){setError('Cable Number must be blank or a whole number of 0 or greater.');return}
  setAdding(true);setError('');
  const {error:addError}=await supabase.from('distribution_box_connections').insert({distribution_box_id:newRow.boxId,cable_number:cable,house_name:newRow.houseName.trim(),meter_number:newRow.meterNumber.trim()||null,account_number:newRow.accountNumber.trim()||null});
  if(addError)setError('Could not add connection: '+addError.message);
  else{setNewRow({boxId:'',cableNumber:'',houseName:'',meterNumber:'',accountNumber:''});const [{data:cables},{data:boxRows}]=await Promise.all([supabase.from('distribution_box_connections').select('id,distribution_box_id,cable_number,house_name,meter_number,account_number'),supabase.from('distribution_boxes').select('id,box_number')]);const names=Object.fromEntries((boxRows||[]).map(x=>[x.id,x.box_number]));setConnections((cables||[]).filter(x=>String(x.house_name||'').trim()&&x.house_name.trim()!=='-').map(x=>({id:x.id,boxId:x.distribution_box_id,boxNumber:names[x.distribution_box_id]||'Unmatched box',cableNumber:x.cable_number,houseName:x.house_name,meterNumber:x.meter_number||'',accountNumber:x.account_number||''})).sort((a,b)=>a.boxNumber.localeCompare(b.boxNumber,undefined,{numeric:true})||a.cableNumber-b.cableNumber))}
  setAdding(false);
 }
 async function removeRow(row){
  if(!window.confirm('Remove cable '+row.cableNumber+' for '+row.houseName+' from '+row.boxNumber+'? This cannot be undone.'))return;
  setSaving(old=>({...old,[row.id]:true}));setError('');
  const {error:deleteError}=await supabase.from('distribution_box_connections').delete().eq('id',row.id);
  if(deleteError)setError('Could not remove '+row.houseName+': '+deleteError.message);else setConnections(old=>old.filter(x=>x.id!==row.id));
  setSaving(old=>({...old,[row.id]:false}));
 }
 return <div className="house-registry"><section className="panel">
  <div className="panelhead"><div><h2>House registry · cable connections</h2><p>Manage the cable supply records and customer meter details</p></div><span className="pill">{filtered.length} shown</span></div>
  <div className="house-summary"><div><b>{connections.length}</b><span>House connections</span></div><div><b>{boxCount}</b><span>Distribution boxes</span></div><div><b>{new Set(connections.map(c=>c.houseName.toLowerCase())).size}</b><span>House names</span></div></div>
  <div className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search box, cable, house, meter or account number"/></div>
  <p className="house-help">Add, edit or remove cable connection records. Physical box installation location is recorded separately from the houses supplied by its cables.</p>
  {error&&<div className="house-error" role="alert">{error}</div>}
  <div className="registry-add-panel"><h3>Add a house connection</h3><div className="registry-add-grid">
   <label>Box Number<select value={newRow.boxId} onChange={e=>setNewRow(v=>({...v,boxId:e.target.value}))}><option value="">Select box</option>{boxes.map(b=><option key={b.id} value={b.id}>{b.box_number}</option>)}</select></label>
   <label>Cable Number<input type="number" min="0" step="1" value={newRow.cableNumber} onChange={e=>setNewRow(v=>({...v,cableNumber:e.target.value}))} placeholder="Cable no. (optional)"/></label>
   <label>House Name<input value={newRow.houseName} onChange={e=>setNewRow(v=>({...v,houseName:e.target.value}))} placeholder="House name"/></label>
   <label>Meter Number<input value={newRow.meterNumber} onChange={e=>setNewRow(v=>({...v,meterNumber:e.target.value}))} placeholder="Meter no. (optional)"/></label>
   <label>Account Number<input value={newRow.accountNumber} onChange={e=>setNewRow(v=>({...v,accountNumber:e.target.value}))} placeholder="Account no. (optional)"/></label>
   <button className="registry-add-button" disabled={adding} onClick={addRow}>{adding?'Adding…':'＋ Add connection'}</button>
  </div></div>
  {loading?<p className="muted">Loading cable connection records…</p>:<div className="house-table-wrap"><table className="house-table"><thead><tr><th>House Name</th><th>Cable Number</th><th>Box Number</th><th>Meter Number</th><th>Account Number</th><th>Actions</th></tr></thead><tbody>
   {filtered.map(row=>{const d=drafts[row.id]||{boxId:row.boxId,cableNumber:row.cableNumber==null?'':String(row.cableNumber),houseName:row.houseName,meterNumber:row.meterNumber,accountNumber:row.accountNumber};const isEditing=editingId===row.id;return <tr key={row.id}>
    <td>{isEditing?<input className="registry-number-input" aria-label={'House Name for '+row.houseName} value={d.houseName} onChange={e=>changeDraft(row.id,'houseName',e.target.value)}/>:<button type="button" className="house-map-link" title={'Show '+row.boxNumber+' on the map'} onClick={()=>onSelectHouse?.(row)}>{row.houseName}</button>}</td>
    <td>{isEditing?<input className="registry-number-input" aria-label={'Cable Number for '+row.houseName} type="number" min="0" step="1" value={d.cableNumber} onChange={e=>changeDraft(row.id,'cableNumber',e.target.value)}/>:row.cableNumber}</td>
    <td>{isEditing?<select className="registry-edit-select" aria-label={'Box Number for '+row.houseName} value={d.boxId} onChange={e=>changeDraft(row.id,'boxId',e.target.value)}>{boxes.map(b=><option key={b.id} value={b.id}>{b.box_number}</option>)}</select>:row.boxNumber}</td>
    <td>{isEditing?<input className="registry-number-input" aria-label={'Meter Number for '+row.houseName} value={d.meterNumber} placeholder="Meter no." onChange={e=>changeDraft(row.id,'meterNumber',e.target.value)}/>:row.meterNumber||'—'}</td>
    <td>{isEditing?<input className="registry-number-input" aria-label={'Account Number for '+row.houseName} value={d.accountNumber} placeholder="Account no." onChange={e=>changeDraft(row.id,'accountNumber',e.target.value)}/>:row.accountNumber||'—'}</td>
    <td><div className="registry-row-actions">{isEditing?<><button className="uploadbtn" disabled={!!saving[row.id]} onClick={()=>saveRow(row)}>{saving[row.id]?'Saving…':'Save'}</button><button className="textbutton" disabled={!!saving[row.id]} onClick={()=>cancelEdit(row)}>Cancel</button></>:<button className="uploadbtn" disabled={!!saving[row.id]||editingId!==null} onClick={()=>startEdit(row)}>Edit</button>}<button className="registry-remove-button" disabled={!!saving[row.id]||editingId!==null} onClick={()=>removeRow(row)}>Remove</button></div></td>
   </tr>})}
   {!filtered.length&&<tr><td colSpan="6" className="house-empty">{search?'No cable connections match your search.':'No cable connection records found.'}</td></tr>}
  </tbody></table></div>}
  <p className="house-footnote">Live shared database · Changes are saved to Supabase and shared across devices.</p>
 </section></div>;
}

function HierarchyPanel(){return <section className="panel hierarchy-panel"><div className="panelhead"><div><h2>Distribution box hierarchy</h2><p>Parent and child identifiers recorded from your chart notes</p></div><span className="pill">11 main groups</span></div><div className="hierarchy-grid">{dbHierarchy.map(group=><details className="hierarchy-group" key={group.name}><summary><span className="tree-parent"><Boxes size={15}/>{group.name}</span><span className="tree-count">{group.groups?(group.groups.length-1)+' parent boxes':group.children.length+' child boxes'}</span></summary>{group.groups?<div className="tree-branches">{group.groups.map(parent=><div className="tree-branch" key={parent.name}><div className="tree-node parent-node"><Boxes size={13}/><b>{parent.name}</b>{parent.children.length>0&&<small>{parent.children.length} child boxes</small>}</div>{parent.children.length>0&&<div className="tree-children">{parent.children.map(child=><span className="tree-child" key={child}>{child}</span>)}</div>}</div>)}</div>:<div className="tree-children direct-children">{group.children.map(child=><span className="tree-child" key={child}>{child}</span>)}</div>}</details>)}</div><p className="hierarchy-footnote">Identifiers are displayed exactly as provided. Child counts are recorded only where you supplied them; empty child lists mean details are still pending. NEW 1, NEW 2 and NEW 3 remain planned boxes and are not included in this installed-box hierarchy.</p></section>}
