useEffect(()=>{let alive=true;const loadHouses=async()=>{const [{data:connections,error:connectionError},{data:boxes,error:boxError}]=await Promise.all([supabase.from('distribution_box_connections').select('id,cable_number,house_name,distribution_box_id').order('cable_number'),supabase.from('distribution_boxes').select('id,box_number,installed_house_name')]);if(!alive)return;if(connectionError||boxError){console.error('Could not load cable connections:',connectionError||boxError);return}const boxById=Object.fromEntries((boxes||[]).map(b=>[b.id,b]));const grouped={};(boxes||[]).forEach(b=>{grouped[b.box_number]={installedHouseName:b.installed_house_name||'',connections:[]}});(connections||[]).forEach(h=>{const box=boxById[h.distribution_box_id];if(box&&h.house_name){(grouped[box.box_number]||(grouped[box.box_number]={installedHouseName:box.installed_house_name||'',connections:[]})).connections.push({id:h.id,cableNumber:h.cable_number,houseName:h.house_name})}});Object.values(grouped).forEach(v=>v.connections.sort((a,b)=>a.cableNumber-b.cableNumber));setHouseNamesByBox(grouped)};loadHouses();const ch=supabase.channel('distribution-box-connections-live').on('postgres_changes',{event:'*',schema:'public',table:'distribution_box_connections'},loadHouses).subscribe();return()=>{alive=false;supabase.removeChannel(ch)}},[]);useEffect(()=>{const t=setTimeout(()=>{if(mapObj.current)mapObj.current.invalidateSize({animate:false})},120);return()=>clearTimeout(t)},[fullScreen]);
