  const boxData=houseNamesByBox[r.code]||{installedHouseName:'',connections:[]};const popupConnections=boxData.connections||[];const escapeHtml=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));const popupHtml='<div class="db-house-popup"><strong>'+r.code+(boxData.installedHouseName?' ('+escapeHtml(boxData.installedHouseName)+')':'')+'</strong>'+(popupConnections.length?'<div class="db-house-popup-count">'+popupConnections.length+' connected '+(popupConnections.length===1?'house':'houses')+'</div><ol>'+popupConnections.map(item=>'<li><strong>Cable '+item.cableNumber+':</strong> '+escapeHtml(item.houseName)+'</li>').join('')+'</ol>':'<div class="db-house-popup-count">No cable connections registered</div>')+'</div>';marker.bindPopup(popupHtml,{maxWidth:260});
